+                deprecation_target = Some(place);
+            }
+
+            let mut resolved_source = ResolvedPlaceLoadSource {
+                place: self.resolve_source(&source),
+                constraint_keys: self.procedure.narrowing_constraints_for(&source),
+                kind: source.kind,
+            };
